function fullTrackEnd(decodedDuration){if(!Number.isFinite(decodedDuration)||decodedDuration<=0)throw Error('無效歌曲長度');return decodedDuration;}
function fullChart(song,difficulty,duration){return song.charts[difficulty].filter(n=>n.t>=0&&n.t<duration&&(!n.end||n.end<=duration));}
function trackBestKey(id,difficulty,revision){return `rhythm.best.v2.${id}.${difficulty}${revision?"."+revision:""}`;}

const $=id=>document.getElementById(id),show=id=>$(id).classList.remove('hidden'),hide=id=>$(id).classList.add('hidden');
const DEFAULT={speed:5,offset:0,volume:80,sfxVolume:55};
function load(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function save(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{}}
let currentSong=SONGS[0],bufferSongId=null;
let prefs={...DEFAULT,...load('setsuna.prefs.v1',{})},diff='normal',autoplay=false,status='home',ctx,gain,hitSounds,buffer,source,startedAt=0,pausedAt=0,resumeAnchor=0,segmentEnd=0,engine,chart=[],runId=0,wakeLock;
let particles=[],flashes=Array(6).fill(0),judgementAt=-100,judgement={},comboPulse=0,held=new Map(),cal=null,lastFrame=0,visibleNotes=[],renderCursor=0,runStats={frames:0,slowFrames:0},lastHUD=0;
const canvas=$('stage'),c=canvas.getContext('2d',{alpha:false});let W=390,H=844,DPR=1;
const renderer=new ReferenceView(c,W,H);let mvURL=null,mvBlocked=false;
const colors={MARVELOUS:'#c0f8ee',PERFECT:'#efceff',GOOD:'#addfff',BAD:'#ffd19c',MISS:'#fb9bae'};
function toast(message){$('toast').textContent=message;$('toast').style.opacity=1;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.opacity=0,3200)}
function fmt(t){return Math.floor(Math.max(0,t)/60)+':'+String(Math.floor(Math.max(0,t)%60)).padStart(2,'0')}
function savedBest(){return load(trackBestKey(currentSong.id,diff,currentSong.chartRevision),null)??(!currentSong.chartRevision&&currentSong.id==='setsuna-hanabi'?load(`setsuna.best.${diff}.full`,null):null);}
function refreshMenu(){let end=currentSong.duration,list=fullChart(currentSong,diff,end);$('chart-count').textContent=`${list.length} 音符 · ${({normal:'NORMAL 06',hard:'HARD 12',extreme:'EXTREME 16'})[diff]} · 全曲 ${fmt(end)}`;let best=savedBest();$('best').textContent=best?String(best.score).padStart(7,'0'):'—';$('full-duration').textContent='全曲演奏 · '+fmt(end)+' · 鼓點／主旋律／伴奏';$('song-index').textContent=String(SONGS.indexOf(currentSong)+1).padStart(2,'0')+' / '+String(SONGS.length).padStart(2,'0');$('song-artist').textContent=currentSong.artist;$('song-title').textContent=currentSong.romanized;$('song-subtitle').textContent=currentSong.title===currentSong.romanized?'FULL SONG':currentSong.title;$('cover-title').textContent=currentSong.title;$('cover-romanized').textContent=currentSong.romanized.toUpperCase();$('cover-art').src=window.EMBEDDED_ASSETS?.[currentSong.cover]??currentSong.cover;$('game-title').textContent=currentSong.title;$('result-title').textContent=currentSong.title;$('result-artist').textContent=currentSong.artist;}
function setLoading(value){$('start').disabled=$('watch').disabled=value;document.querySelectorAll('[data-song]').forEach(b=>b.disabled=value);}
function selectSong(id){if(status==='loading')return;const selected=SONGS.find(s=>s.id===id);if(!selected||selected===currentSong)return;currentSong=selected;buffer=null;bufferSongId=null;renderer.image.src=window.EMBEDDED_ASSETS?.[selected.cover]??selected.cover;$('mv-clear').click();document.querySelectorAll('[data-song]').forEach(b=>{let active=b.dataset.song===id;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active));});refreshMenu();}
function renderSongOptions(){const host=$('song-options');host.replaceChildren();for(const song of SONGS){let b=document.createElement('button');b.dataset.song=song.id;b.className='song-choice'+(song===currentSong?' selected':'');b.setAttribute('aria-pressed',String(song===currentSong));const title=document.createElement('strong'),detail=document.createElement('small');title.textContent=song.romanized;detail.textContent=song.artist+' · '+fmt(song.duration);b.append(title,detail);b.onclick=()=>selectSong(song.id);host.append(b);}}
function refreshSettings(){for(let key of ['speed','offset','volume','sfxVolume'])$(key).value=prefs[key];$('speed-value').textContent=Number(prefs.speed).toFixed(1);$('offset-value').textContent=(prefs.offset>0?'+':'')+prefs.offset+' ms';$('volume-value').textContent=prefs.volume+'%';$('sfxVolume-value').textContent=prefs.sfxVolume===0?'靜音':prefs.sfxVolume+'%';if(gain)gain.gain.value=prefs.volume/100;if(hitSounds)hitSounds.setVolume(prefs.sfxVolume);}
for(let button of document.querySelectorAll('[data-diff]'))button.onclick=()=>{diff=button.dataset.diff;document.querySelectorAll('[data-diff]').forEach(b=>b.classList.toggle('selected',b===button));refreshMenu()};
for(let key of ['speed','offset','volume','sfxVolume'])$(key).oninput=()=>{prefs[key]=Number($(key).value);save('setsuna.prefs.v1',prefs);refreshSettings()};
function changeOffset(d){prefs.offset=Math.max(-300,Math.min(300,prefs.offset+d));refreshSettings();save('setsuna.prefs.v1',prefs)}
$('offset-minus').onclick=()=>changeOffset(-5);$('offset-plus').onclick=()=>changeOffset(5);$('offset-zero').onclick=()=>{prefs.offset=0;refreshSettings();save('setsuna.prefs.v1',prefs)};
$('sfx-preview').onclick=async()=>{await audio();hitSounds.play('tap');};
$('settings-open').onclick=()=>show('settings');$('tutorial-open').onclick=$('help').onclick=()=>show('tutorial');
for(let button of document.querySelectorAll('[data-close]'))button.onclick=()=>{hide(button.dataset.close);if(button.dataset.close==='settings')stopCalibration()};
async function audio(){if(!ctx){ctx=new(window.AudioContext||window.webkitAudioContext)({latencyHint:'interactive'});gain=ctx.createGain();gain.gain.value=prefs.volume/100;gain.connect(ctx.destination);hitSounds=new HitSounds(ctx);hitSounds.setVolume(prefs.sfxVolume);ctx.onstatechange=()=>{if(ctx.state!=='running'&&status==='playing')pause('聲音播放被中斷，請點繼續。')};}await ctx.resume();return ctx;}
async function getSong(){if(buffer&&bufferSongId===currentSong.id)return buffer;const selected=currentSong;let bytes,embedded=window.EMBEDDED_AUDIO?.[selected.id];if(embedded){let raw=atob(embedded),arr=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)arr[i]=raw.charCodeAt(i);bytes=arr.buffer;}else{const response=await fetch(selected.audio);if(!response.ok)throw Error('無法讀取歌曲');bytes=await response.arrayBuffer();}buffer=await ctx.decodeAudioData(bytes.slice(0));bufferSongId=selected.id;return buffer;}
function stopSource(){hitSounds?.stop();if(source){source.onended=null;try{source.stop()}catch{}source.disconnect();source=null;}}
function heardTime(perf=performance.now()){if(!ctx)return 0;const stamp=ctx.getOutputTimestamp?.();let t;if(stamp&&stamp.contextTime>0&&stamp.performanceTime>0&&Math.abs(performance.now()-stamp.performanceTime)<1000){t=stamp.contextTime+(perf-stamp.performanceTime)/1000;}else t=ctx.currentTime-(ctx.outputLatency??ctx.baseLatency??0);return t-startedAt;}
function songTime(perf=performance.now()){return timeline(heardTime(perf),resumeAnchor,prefs.offset).chart;}
function eventPerf(e){let t=e.timeStamp;if(t>1e12)t-=performance.timeOrigin;return Math.abs(t-performance.now())<200?t:performance.now()}
async function schedule(offset,count=3){resumeAnchor=offset;mvBlocked=false;if(renderer.video){renderer.video.pause();renderer.video.currentTime=Math.min(offset,Math.max(0,renderer.video.duration-.1));}stopSource();await audio();source=ctx.createBufferSource();source.buffer=buffer;source.connect(gain);startedAt=ctx.currentTime+count-offset;source.start(ctx.currentTime+count,offset,Math.max(0,segmentEnd-offset));source.onended=null;}
async function start(auto=false){if(status==='loading')return;stopCalibration();status='loading';setLoading(true);$('start').textContent='準備音訊…';const token=++runId;try{await audio();await getSong();if(token!==runId)return;autoplay=auto;segmentEnd=fullTrackEnd(buffer.duration);chart=fullChart(currentSong,diff,segmentEnd);engine=new Engine(chart,onJudge);renderer.effects=[];particles=[];flashes.fill(0);held.clear();visibleNotes=[];renderCursor=0;judgementAt=-100;runStats={frames:0,slowFrames:0};lastFrame=0;lastHUD=0;hide('home');hide('results');hide('pause-sheet');show('game');document.body.classList.add('playing');$('game-mode').textContent=`${diff.toUpperCase()} / FULL SONG`;$('auto-label').textContent=auto?'AUTO PLAY · 不計成績':'';$('speed-label').textContent=`SPEED ${Number(prefs.speed).toFixed(1)}`;resize();await schedule(0,3);status='playing';if('wakeLock'in navigator)try{wakeLock=await navigator.wakeLock.request('screen')}catch{}requestAnimationFrame(frame);}catch(error){status='home';show('home');hide('game');document.body.classList.remove('playing');toast('音訊未能開始：'+error.message)}finally{setLoading(false);$('start').innerHTML='開始演奏 <span>↗</span>';}}
function onJudge(j){if(j.quality!=='MISS')hitSounds?.play(j.tick?'trace':j.tail?'tail':j.n.type==='flick'?'flick':'tap');if(j.tick){renderer.hit(j.lane,true);return;}judgement=j;judgementAt=performance.now();comboPulse=1;let lane=j.tail?j.n.endLane:j.n.lane;if(j.quality!=='MISS')renderer.hit(lane,j.n.accent==='gold'||Boolean(j.n.end));}
$('start').onclick=()=>start(false);$('watch').onclick=()=>start(true);$('play-again').onclick=()=>start(autoplay);$('retry').onclick=()=>start(autoplay);
function pause(reason='準備好再回到節奏。'){if(status!=='playing')return;pausedAt=Math.max(0,Math.min(segmentEnd,heardTime()));status='paused';$('mv-video').pause();stopSource();engine.suspend();held.clear();$('pause-reason').textContent=reason;show('pause-sheet');$('countdown').textContent='';$('live-judge').style.opacity=0;}
$('pause').onclick=()=>pause();$('resume').onclick=async()=>{if(status!=='paused')return;$('resume').disabled=true;try{await schedule(pausedAt,1.5);hide('pause-sheet');status='playing';lastFrame=0;requestAnimationFrame(frame)}catch(e){toast('點擊繼續以重新啟用聲音')}finally{$('resume').disabled=false}};
function home(){runId++;status='home';$('mv-video').pause();stopSource();held.clear();wakeLock?.release().catch(()=>{});wakeLock=null;hide('pause-sheet');hide('results');hide('game');show('home');document.body.classList.remove('playing');refreshMenu();}
$('quit').onclick=$('result-home').onclick=home;
document.addEventListener('visibilitychange',()=>{if(document.hidden){pause('切換頁面後已自動暫停。');stopCalibration();}});window.addEventListener('pagehide',()=>pause());
function finish(){if(status!=='playing')return;engine.update(segmentEnd+1);status='results';$('mv-video').pause();stopSource();wakeLock?.release().catch(()=>{});wakeLock=null;let s=engine.stats,acc=engine.accuracy,score=engine.score;const bestKey=trackBestKey(currentSong.id,diff,currentSong.chartRevision),best=savedBest();let improved=!autoplay&&(!best||score>best.score);if(improved)save(bestKey,{score,accuracy:acc,maxCombo:s.maxCombo,date:new Date().toISOString()});$('result-mode').textContent=autoplay?'AUTO':diff.toUpperCase();$('grade').textContent=acc>=99?'S+':acc>=95?'S':acc>=90?'A':acc>=80?'B':acc>=65?'C':'D';$('result-score').textContent=String(score).padStart(7,'0');$('result-accuracy').textContent=acc.toFixed(2)+'%';$('result-combo').textContent=s.maxCombo;$('new-best').textContent=autoplay?'AUTO PLAY · 不儲存成績':improved?'✧ NEW PERSONAL BEST':s.miss===0&&s.bad===0?'✧ FULL COMBO':'';$('judgement-list').innerHTML=['MARVELOUS','PERFECT','GOOD','BAD','MISS'].map(q=>`<div><span style="color:${colors[q]}">${q}</span><b>${s[q.toLowerCase()]}</b></div>`).join('');let d=s.deltas.slice().sort((a,b)=>a-b),median=d.length?d[Math.floor(d.length/2)]:0;$('timing-summary').textContent=autoplay?'演示只展示操作路徑；不代表實機觸控延遲已驗證。':d.length?`中位判定偏差 ${median>=0?'+':''}${median.toFixed(0)} ms · ${s.judged}/${engine.total} 判定`:'未有命中音符；可先用自動演示熟悉節奏。';show('results');refreshMenu();}
function resize(){let rect=$('game').getBoundingClientRect();W=$('game').clientWidth||innerWidth;H=$('game').clientHeight||innerHeight;DPR=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(W*DPR);canvas.height=Math.round(H*DPR);c.setTransform(DPR,0,0,DPR,0,0);renderer.resize(W,H);}
window.addEventListener('resize',()=>{if(status!=='home')resize()});
function stagePoint(e){let r=canvas.getBoundingClientRect();return toStage(e.clientX,e.clientY,r,W,H);}
function laneInput(x,y){return inputLane(x,renderer.g);}
function validInput(e){return stagePoint(e).y>=H*.53;}
canvas.addEventListener('pointerdown',e=>{e.preventDefault();if(status!=='playing'||autoplay||!validInput(e))return;let {x,y}=stagePoint(e),lane=laneInput(x,y);if(lane<-.5||lane>5.5)return;let id=e.pointerId;try{canvas.setPointerCapture(id)}catch{}held.set(id,{x,y,lastX:x,lastY:y,perf:eventPerf(e),flicked:false});engine.down(id,lane,songTime(eventPerf(e)));flashes[Math.max(0,Math.min(5,Math.round(lane)))]=.5;},{passive:false});
canvas.addEventListener('pointermove',e=>{e.preventDefault();let h=held.get(e.pointerId);if(!h||status!=='playing')return;let {x,y}=stagePoint(e),t=songTime(eventPerf(e)),lane=laneInput(x,y);engine.move(e.pointerId,lane,t);if(h.y-y>=Math.max(12,H*.018)&&eventPerf(e)-h.perf<350&&!h.flicked){let result=engine.flick(e.pointerId,laneInput(h.x,h.y),t);if(result)h.flicked=true;}if(eventPerf(e)-h.perf>350||y>h.y){h.x=x;h.y=y;h.perf=eventPerf(e);h.flicked=false;}h.lastX=x;h.lastY=y;},{passive:false});
function pointerUp(e){e.preventDefault();if(held.has(e.pointerId)){engine?.up(e.pointerId,songTime(eventPerf(e)));held.delete(e.pointerId);}}
canvas.addEventListener('pointerup',pointerUp,{passive:false});canvas.addEventListener('pointercancel',pointerUp,{passive:false});canvas.addEventListener('lostpointercapture',e=>{if(held.has(e.pointerId))pointerUp(e)});canvas.addEventListener('contextmenu',e=>e.preventDefault());
const keys=['s','d','f','j','k','l'];document.addEventListener('keydown',e=>{if(e.key==='Escape'&&status==='playing'){pause();return;}let lane=keys.indexOf(e.key.toLowerCase());if(lane<0||e.repeat||status!=='playing'||autoplay)return;e.preventDefault();engine.down('key'+lane,lane,songTime());engine.flick('key'+lane,lane,songTime());flashes[lane]=.7;});document.addEventListener('keyup',e=>{let lane=keys.indexOf(e.key.toLowerCase());if(lane>=0&&status==='playing'&&!autoplay)engine.up('key'+lane,songTime());});
function background(t){renderer.background(t);}
function track(t,dt){renderer.track(t,dt);}
function drawNote(n,t){renderer.note(n,t,engine,3.9/(.65+prefs.speed*.43));}
function autoStep(t){for(let n of engine.notes){if(n.state==='pending'&&t>=n.t){engine.down('auto'+n.id,n.lane,n.t);if(n.type==='flick')engine.flick('auto'+n.id,n.lane,n.t);}if(n.end&&n.state==='hit'&&!n.tail)engine.move('auto'+n.id,engine.laneAt(n,t),t);}engine.update(t);for(let n of engine.notes)if(n.tail&&engine.fingers.has('auto'+n.id))engine.up('auto'+n.id,t);}
function frame(perf){if(status!=='playing')return;let dt=lastFrame?Math.min(.05,(perf-lastFrame)/1000):1/60;if(lastFrame&&perf-lastFrame>25)runStats.slowFrames++;runStats.frames++;lastFrame=perf;let raw=heardTime(perf),clock=timeline(raw,resumeAnchor,prefs.offset),t=clock.chart;if(clock.active){if(autoplay)autoStep(t);else engine.update(t);}syncMV(raw,clock.active);background(t);track(t,dt);const flight=3.9/(.65+prefs.speed*.43);while(renderCursor<engine.notes.length&&engine.notes[renderCursor].t<t+flight+.2)visibleNotes.push(engine.notes[renderCursor++]);visibleNotes=visibleNotes.filter(n=>(n.end??n.t)>t-.3&&!(n.state==='miss')&&!(n.state==='hit'&&(!n.end||n.tail)));for(let i=visibleNotes.length-1;i>=0;i--)drawNote(visibleNotes[i],t);
 renderer.effectsFrame(dt);let judgeAge=(perf-judgementAt)/1000;renderer.judgement(engine.stats,judgement,judgeAge,comboPulse);renderer.hud(engine.score,engine.accuracy,engine.stats);comboPulse=Math.max(0,comboPulse-dt*4);
 let age=(perf-judgementAt)/1000;$('live-judge').style.opacity=0;let h=heardTime(perf);$('countdown').textContent=clock.countdown<0?(clock.countdown>-.6?'READY':String(Math.ceil(-clock.countdown))):'';
 if(perf-lastHUD>50){$('score').textContent=String(engine.score).padStart(7,'0');$('accuracy').textContent=engine.accuracy.toFixed(2)+'%';$('time-left').textContent=fmt(segmentEnd-h);$('progress-fill').style.width=Math.max(0,Math.min(100,h/segmentEnd*100))+'%';lastHUD=perf;}if(h>=segmentEnd+.15){finish();return;}requestAnimationFrame(frame);}
// Calibration uses scheduled clicks and the same audible-output clock as gameplay.
function stopCalibration(){if(!cal)return;clearInterval(cal.timer);for(let osc of cal.oscs)try{osc.stop()}catch{}cal=null;$('calibrate').textContent='開始校正';show('calibrate');hide('cal-tap');}
$('calibrate').onclick=async()=>{try{await audio();stopCalibration();const first=ctx.currentTime+1;cal={first,next:0,taps:[],oscs:[]};$('calibration-info').textContent='先聽兩拍，再跟住聲音點 8 下。';hide('calibrate');show('cal-tap');function scheduleClicks(){if(!cal)return;while(cal.first+cal.next*.6<ctx.currentTime+1){const at=cal.first+cal.next*.6;let osc=ctx.createOscillator(),g=ctx.createGain();osc.type='sine';osc.frequency.value=cal.next%4===0?1100:800;g.gain.setValueAtTime(0,at);g.gain.linearRampToValueAtTime(.18,at+.002);g.gain.exponentialRampToValueAtTime(.0001,at+.05);osc.connect(g);g.connect(ctx.destination);osc.start(at);osc.stop(at+.06);cal.oscs.push(osc);if(cal.oscs.length>12)cal.oscs.shift();cal.next++;}}scheduleClicks();cal.timer=setInterval(scheduleClicks,150);}catch{toast('請再點一次開始校正')}};
$('cal-tap').addEventListener('pointerdown',e=>{e.preventDefault();if(!cal)return;let audible=heardTime(eventPerf(e))+startedAt;let beat=(audible-cal.first)/.6,index=Math.round(beat);if(index<2){toast('先聽兩拍，再跟住點按');return;}if(cal.lastIndex===index)return;cal.lastIndex=index;let delta=(beat-index)*600;if(Math.abs(delta)>250)return;cal.taps.push(delta);$('calibration-info').textContent=`已收集 ${cal.taps.length} / 8 次點按`;if(cal.taps.length>=8){let v=cal.taps.slice().sort((a,b)=>a-b),median=(v[3]+v[4])/2,spread=v[6]-v[1];stopCalibration();if(spread>100){$('calibration-info').textContent='點按偏差較大，請重新校正或手動調整。';return;}prefs.offset=Math.max(-300,Math.min(300,Math.round(median/5)*5));save('setsuna.prefs.v1',prefs);refreshSettings();$('calibration-info').textContent=`已套用 ${prefs.offset>=0?'+':''}${prefs.offset} ms；可試玩後再微調。`;}});
refreshSettings();

function syncMV(raw,active){let v=renderer.video;if(!v||!active||raw<0||raw>=v.duration)return;if(Math.abs(v.currentTime-raw)>.16)v.currentTime=raw;if(v.paused&&!mvBlocked){mvBlocked=true;v.play().then(()=>{mvBlocked=false}).catch(()=>{mvBlocked=true});}}
$('mv-select').onclick=()=>$('mv-file').click();
$('mv-file').onchange=()=>{let file=$('mv-file').files[0];if(!file)return;if(mvURL)URL.revokeObjectURL(mvURL);let v=$('mv-video');v.pause();mvURL=URL.createObjectURL(file);v.src=mvURL;v.muted=true;v.onloadedmetadata=()=>{renderer.video=v;$('mv-status').textContent='已載入：'+file.name;toast('已載入本機 MV，演奏時同步播放');};v.onerror=()=>toast('Safari 未能讀取呢個影片格式，請試 MP4（H.264）。');};
$('mv-clear').onclick=()=>{let v=$('mv-video');v.pause();v.removeAttribute('src');v.load();renderer.video=null;if(mvURL)URL.revokeObjectURL(mvURL);mvURL=null;$('mv-file').value='';$('mv-status').textContent='預設使用歌曲內附封面';};

renderSongOptions();refreshMenu();
